{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE saadaa-wh.maplemonk.GROSS_ORDERS_CONSOLIDATED AS SELECT Customer_ID_Final ,Acquisition_Date ,First_Complete_Order_Date ,Maple_monk_id_phone ,customer_id ,Order_Date ,Order_Time ,Shop_Name ,Marketplace ,Channel ,Source ,Order_ID ,Reference_Code ,Saleorderitemcode ,Sales_Order_Item_ID ,Phone ,Name ,Email ,cast(Shipping_Last_Update_Date as datetime) as Shipping_Last_Update_Date ,sku as Order_Sku ,product_id as Order_Product_ID ,product_name as Order_Product_Name ,Currency ,City ,State ,Order_Status ,Quantity ,Gross_Sales_Before_Tax ,Discount ,Tax ,Shipping_Price ,Selling_Price ,OMS_order_status ,Shipping_Status ,Final_Shipping_Status ,AWB ,Payment_Gateway ,Payment_Mode ,Courier ,DISPATCH_DATE as Order_Dispatch_Date ,Delivered_Date as Order_Delivered_Date ,Delivered_Status as Order_Delivered_Status ,Return_Flag ,Returned_Quantity ,Returned_Sales ,Cancelled_Quantity ,Days_in_Shipment ,Marketplace_Acquisition_Date ,Sku_Code ,Product_Name_Final ,Product_Category ,Product_Sub_Category ,CommonSku ,Warehouse ,Pincode ,Source_Pincode ,Source_Name ,Mapped_Source_name ,Order_Type ,Invoice_date ,New_Customer_Flag ,New_Customer_Flag_Month ,Acquisition_Product ,Acquisition_Channel ,Acquisition_Marketplace ,cast(null as string) return_request_type ,cast(null as string) return_approval_status FROM saadaa-wh.`MAPLEMONK.SAADAA_sales_consolidated` WHERE reference_code NOT IN ( SELECT distinct order_name FROM saadaa-wh.`MAPLEMONK.SAADAA_RETURNSPRIME_CONSOLIDATED` WHERE return_approval_status <> \'rejected\' ) UNION ALL SELECT null as Customer_ID_Final ,s.shopify_acquisition_date as Acquisition_Date ,NULL as First_Complete_Order_Date ,s.Maple_monk_id_phone ,s.customer_id ,safe_cast(parse_datetime(\'%Y-%m-%d %H:%M:%S\', trim(regexp_replace(cast(s.order_timestamp as string), r\'(\+05:30|\+00|\sutc)$\', \'\'))) as date) as Order_Date ,parse_datetime(\'%Y-%m-%d %H:%M:%S\', trim(regexp_replace(cast(s.order_timestamp as string), r\'(\+05:30|\+00|\sutc)$\', \'\'))) as Order_Time ,s.Shop_Name ,s.Marketplace ,s.Final_Utm_Channel as Channel ,s.FINAL_UTM_SOURCE as Source ,s.Order_ID ,s.order_name as reference_code ,CAST(r.order_item_id AS STRING) as saleorderitemcode ,null as sales_order_item_id ,s.phone ,s.name ,s.email ,parse_datetime(\'%Y-%m-%d %H:%M:%S\', trim(regexp_replace(regexp_replace(cast(coalesce(cast(s.shipping_status_update_date as string), cast(e.shipping_last_update_date as string)) as string), r\'T\', \' \'), r\'(\+05:30|\+00|\sutc)$\', \'\'))) as Shipping_Last_Update_Date ,s.sku as Order_Sku ,s.product_id as Order_Product_ID ,r.returned_product_name as Order_Product_Name ,s.Currency ,s.City ,s.State ,UPPER(coalesce(r.return_request_type,s.order_status)) as Order_Status ,s.Quantity ,s.Gross_Sales_Before_Tax ,s.Discount ,s.Tax ,s.Shipping_Price ,s.total_sales ,UPPER(e.order_status) as OMS_order_status ,coalesce(r.shipping_status,s.shipping_status,e.shipping_status) as Shipping_Status ,coalesce(r.shipping_status,shipmap.final_shipping_status) as FINAL_SHIPPING_STATUS ,s.awb ,s.Gateway ,s.Payment_Mode ,UPPER(coalesce(e.courier,s.Courier)) as Courier ,coalesce(cast(timestamp(s.Shipping_created_at) as date),cast(timestamp(e.manifest_date) as date)) as Order_Dispatch_Date ,coalesce(cast(timestamp(e.delivered_date) as date),case when s.shipping_status like \'delivered\' then cast(timestamp(s.shipping_status_update_date) as date) end) as Order_Delivered_Date ,case when lower(coalesce(shipmap.final_shipping_status,s.shipping_status, e.shipping_status)) = \'delivered\' then 1 else 0 end AS Order_Delivered_Status ,r.return_flag as Return_Flag ,abs(r.returned_quantity) as Returned_Quantity ,cast(r.returned_product_price as float64) as Returned_Sales ,case when lower(s.order_status) in (\'cancelled\') then cast(quantity as INT64) end cancelled_quantity ,NULL as Days_in_Shipment ,cast(replace(cast(s.shopify_acquisition_date AS string),\'+05:30\',\'\')as date) as Marketplace_Acquisition_Date ,s.Sku_Code ,UPPER(coalesce(s.PRODUCT_NAME_FINAL,e.productname)) as Product_Name_Final ,UPPER(coalesce(s.PRODUCT_CATEGORY,e.category)) Product_Category ,UPPER(s.PRODUCT_SUB_CATEGORY) Product_Sub_Category ,coalesce(case when s.commonsku =\'\' then null else s.commonsku end, e.master_sku) CommonSku ,UPPER(e.warehouse_name) as Warehouse ,coalesce(s.pincode,e.pincode) as pincode ,e.pickup_pincode as source_pincode ,upper(s.source_name) Source_name ,null Mapped_Source_Name ,r.return_request_type as Order_Type ,cast(replace(cast(e.invoice_date AS string),\'+05:30\',\'\')as timestamp) as Invoice_date ,null as New_Customer_Flag ,cast(null as string) as New_Customer_Flag_Month ,cast(null as string) as Acquisition_Product ,cast(null as string) as Acquisition_Channel ,cast(null as string) as Acquisition_Marketplace ,r.return_request_type ,r.return_approval_status FROM saadaa-wh.MAPLEMONK.SAADAA_RETURNSPRIME_CONSOLIDATED r LEFT JOIN saadaa-wh.maplemonk.SAADAA_SHOPIFY_FACT_ITEMS s ON s.order_name = r.order_name and s.LINE_ITEM_ID = r.order_item_id LEFT JOIN (select * from ( select * ,row_number()over(partition by reference_code, Marketplace_LineItem_ID order by last_update_date desc) rw from maplemonk.SAADAA_EasyEcom_FACT_ITEMS ) z where z.rw = 1 and lower(marketplace) like any (\'%shopify%\') ) E on replace(s.order_name,\'#\',\'\') = replace(e.reference_code,\'#\',\'\') and replace(s.LINE_ITEM_ID,\'`\',\'\')=replace(e.Marketplace_LineItem_ID,\'`\',\'\') LEFT JOIN ( select * from ( select upper(Shipping_status) shipping_status ,upper(mapped_status) final_shipping_status ,row_number() over (partition by lower(shipping_Status) order by 1) rw from maplemonk.shipment_status_mapping ) where rw = 1 ) ShipMap on lower(coalesce(r.shipping_status,s.shipping_status,e.shipping_status)) = lower(ShipMap.shipping_status) WHERE lower(r.return_approval_status) <> \'rejected\' ; CREATE OR REPLACE TABLE saadaa-wh.maplemonk.saadaa_gmv_consolidated as WITH Gross_sales_with_tax AS ( SELECT cast(Invoice_date as date) Invoice_Date, Marketplace, \'Gross Sales with Tax\' as Particulars, count(distinct reference_code) as Total_Orders, sum(ifnull(quantity,0)) as Total_Quantity, sum(ifnull(selling_price,0)) - (sum(ifnull(selling_price,0)) * cast(max(sm.tax_rate) as float64)) as Total_Taxable_Amount, sum(ifnull(selling_price,0)) * cast(max(sm.tax_rate) as float64) as GST, sum(ifnull(selling_price,0)) as Invoice_Value, safe_divide(sum(ifnull(selling_price,0)),sum(ifnull(quantity,0))) as Average_Selling_Price_per_Unit, safe_divide(sum(ifnull(selling_price,0)),count(distinct reference_code)) as Average_Order_Value, Null as Total_Number_of_Customers FROM saadaa-wh.maplemonk.gross_orders_consolidated gs LEFT JOIN saadaa-wh.`MAPLEMONK.EasyEcom_SAADAA_product_master` sm ON gs.order_sku = sm.sku GROUP BY 1,2,3 ), GMV AS ( SELECT cast(Invoice_date as date) Invoice_Date, Marketplace, \'GMV\' as Particulars, count(distinct reference_code) as Total_Orders, sum(ifnull(quantity,0)) as Total_Quantity, sum(ifnull(selling_price,0)) - (sum(ifnull(selling_price,0)) * cast(max(sm.tax_rate) as float64)) as Total_Taxable_Amount, sum(ifnull(selling_price,0)) * cast(max(sm.tax_rate) as float64) as GST, sum(ifnull(selling_price,0)) as Invoice_Value, safe_divide(sum(ifnull(selling_price,0)),sum(ifnull(quantity,0))) as Average_Selling_Price_per_Unit, safe_divide(sum(ifnull(selling_price,0)),count(distinct reference_code)) as Average_Order_Value, Null as Total_Number_of_Customers FROM saadaa-wh.maplemonk.gross_orders_consolidated gs LEFT JOIN saadaa-wh.`MAPLEMONK.EasyEcom_SAADAA_product_master` sm ON gs.order_sku = sm.sku WHERE lower(return_request_type) <> \'exchange\' GROUP BY 1,2,3 ), Cancellations AS ( SELECT cast(Invoice_date as date) Invoice_Date, Marketplace, \'Cancellations\' as Particulars, count(distinct reference_code) as Total_Orders, sum(ifnull(quantity,0)) as Total_Quantity, sum(ifnull(selling_price,0)) - (sum(ifnull(selling_price,0)) * cast(max(sm.tax_rate) as float64)) as Total_Taxable_Amount, sum(ifnull(selling_price,0)) * cast(max(sm.tax_rate) as float64) as GST, sum(ifnull(selling_price,0)) as Invoice_Value, safe_divide(sum(ifnull(selling_price,0)),sum(ifnull(quantity,0))) as Average_Selling_Price_per_Unit, safe_divide(sum(ifnull(selling_price,0)),count(distinct reference_code)) as Average_Order_Value, Null as Total_Number_of_Customers FROM saadaa-wh.maplemonk.gross_orders_consolidated gs LEFT JOIN saadaa-wh.`MAPLEMONK.EasyEcom_SAADAA_product_master` sm ON gs.order_sku = sm.sku WHERE lower(oms_order_status) like \'%cancel%\' GROUP BY 1,2,3 ), Gross_Sales as ( select g.Invoice_Date, g.Marketplace, \'Gross Sales\' as Particulars, (g.Total_Orders - c.Total_Orders) as Total_Orders, (g.Total_Quantity - c.Total_Quantity) as Total_Quantity, (g.Total_Taxable_Amount - c.Total_Taxable_Amount) as Total_Taxable_Amount, (g.GST - c.GST) as GST, (g.Invoice_Value - c.Invoice_Value) as Invoice_Value, safe_divide((g.Invoice_Value - c.Invoice_Value),(g.Total_Quantity - c.Total_Quantity)) as Average_Selling_Price_per_Unit, safe_divide((g.Invoice_Value - c.Invoice_Value),(g.Total_Orders - c.Total_Orders)) as Average_Order_Value, Null as Total_Number_of_Customers from gross_sales_with_tax g left join cancellations c on g.invoice_date = c.invoice_date and g.marketplace = c.marketplace ), Returns AS ( SELECT cast(Invoice_date as date) Invoice_Date, Marketplace, \'Returns\' as Particulars, count(distinct reference_code) as Total_Orders, sum(ifnull(quantity,0)) as Total_Quantity, sum(ifnull(selling_price,0)) - (sum(ifnull(selling_price,0)) * cast(max(sm.tax_rate) as float64)) as Total_Taxable_Amount, sum(ifnull(selling_price,0)) * cast(max(sm.tax_rate) as float64) as GST, sum(ifnull(selling_price,0)) as Invoice_Value, safe_divide(sum(ifnull(selling_price,0)),sum(ifnull(quantity,0))) as Average_Selling_Price_per_Unit, safe_divide(sum(ifnull(selling_price,0)),count(distinct reference_code)) as Average_Order_Value, Null as Total_Number_of_Customers FROM saadaa-wh.maplemonk.gross_orders_consolidated gs LEFT JOIN saadaa-wh.`MAPLEMONK.EasyEcom_SAADAA_product_master` sm ON gs.order_sku = sm.sku WHERE lower(return_request_type) = \'return\' GROUP BY 1,2,3 ), Exchanges AS ( SELECT cast(Invoice_date as date) Invoice_Date, Marketplace, \'Exchanges\' as Particulars, count(distinct reference_code) as Total_Orders, sum(ifnull(quantity,0)) as Total_Quantity, sum(ifnull(selling_price,0)) - (sum(ifnull(selling_price,0)) * cast(max(sm.tax_rate) as float64)) as Total_Taxable_Amount, sum(ifnull(selling_price,0)) * cast(max(sm.tax_rate) as float64) as GST, sum(ifnull(selling_price,0)) as Invoice_Value, safe_divide(sum(ifnull(selling_price,0)),sum(ifnull(quantity,0))) as Average_Selling_Price_per_Unit, safe_divide(sum(ifnull(selling_price,0)),count(distinct reference_code)) as Average_Order_Value, Null as Total_Number_of_Customers FROM saadaa-wh.maplemonk.gross_orders_consolidated gs LEFT JOIN saadaa-wh.`MAPLEMONK.EasyEcom_SAADAA_product_master` sm ON gs.order_sku = sm.sku WHERE lower(return_request_type) = \'exchange\' GROUP BY 1,2,3 ), Net_Sales as ( select g.Invoice_Date, g.Marketplace, \'Net Sales\' as Particulars, (g.Total_Orders - r.Total_Orders) as Total_Orders, (g.Total_Quantity - r.Total_Quantity) as Total_Quantity, (g.Total_Taxable_Amount - r.Total_Taxable_Amount) as Total_Taxable_Amount, (g.GST - r.GST) as GST, (g.Invoice_Value - r.Invoice_Value) as Invoice_Value, safe_divide((g.Invoice_Value - r.Invoice_Value),(g.Total_Quantity - r.Total_Quantity)) as Average_Selling_Price_per_Unit, safe_divide((g.Invoice_Value - r.Invoice_Value),(g.Total_Orders - r.Total_Orders)) as Average_Order_Value, Null as Total_Number_of_Customers from gross_sales_with_tax g left join returns r on g.invoice_date = r.invoice_date and g.marketplace = r.marketplace ) SELECT * FROM Gross_sales_with_tax UNION ALL SELECT * FROM GMV UNION ALL SELECT * FROM Cancellations UNION ALL SELECT * FROM Gross_Sales UNION ALL SELECT * FROM Returns UNION ALL SELECT * FROM Exchanges UNION ALL SELECT * FROM Net_Sales ;",
